logic:
if (element.dataset.bannerInjected) return;
element.dataset.bannerInjected = 'true';

var banner = document.createElement('div');
banner.style.border = '2px solid #d4a017';
banner.style.background = '#fff9e6';
banner.style.padding = '12px 16px';
banner.style.marginBottom = '16px';
banner.style.borderRadius = '6px';
banner.style.fontWeight = 'bold';

var link = document.createElement('a');
link.href = 'https://community.fandom.com/wiki/Help:Admin_Dashboard';
link.target = '_blank';
link.style.color = '#520044';
link.style.textDecoration = 'underline';
link.style.fontWeight = 'bold';
link.textContent = 'Admin Dashboard';

var text = document.createElement('span');
text.innerHTML = ' Need to configure wiki settings? Go directly to the ';

var instructions = document.createTextNode(' — click "Admin" on your bottom toolbar to find it.');

banner.appendChild(text);
banner.appendChild(link);
banner.appendChild(instructions);

element.insertBefore(banner, element.firstChild);
